import { useState, useContext } from "react";
import { useNavigate, Link } from "react-router-dom";
import { AuthContext } from "../context/AuthContext";

import "../components/general.css";
import Headerreg from "../components/Header_reg";

export default function LoginAdminCode() {
  const [codigo, setCodigo] = useState("");
  const [errorMessage, setErrorMessage] = useState(null);
  const { verifyAdminCode } = useContext(AuthContext);
  const navigate = useNavigate();

  const handleSubmit = async (e) => {    
  e.preventDefault();
  setErrorMessage(null);

    const result = await verifyAdminCode(codigo.trim());

    if (result.success) {
      navigate("/panel_control"); 
    } else {
      alert(result.message || "Error al verificar el código.");
    }
  };

  const volver = () => {
    sessionStorage.removeItem('pendingUser');
    navigate("/login");
  };

  return (
    <>
      <Headerreg /> 

        <main> 
            <div className="contenedor">
              <div className="formulario_inicio">
                <h2>Iniciar sesión</h2>

                  <form onSubmit={handleSubmit}>
                    <p>
                      Estás ingresando como administrador, para continuar ingresa tu código
                    </p>

                        <label htmlFor="codigo">Código de administrador</label>
                        <input
                          type="password"
                          id="codigo"
                          name="codigo"
                          placeholder="Ingresa tu código de administrador"
                          required
                          value={codigo}
                          onChange={(e) => setCodigo(e.target.value)}
                        />

                        <button type="submit">Ingresar</button>
                        <button type="button" onClick={volver}>Volver</button>
                  </form>
                </div>
            </div>
        </main>
      </>
  );
}
